// ============================================================================
// Meong Tales — Story Engine
// ----------------------------------------------------------------------------
// Two paths, one output shape:
//   1. TEMPLATE (demo mode, always works offline): assembles a complete
//      5-page story from the VERIFIED content bank. Nothing is invented.
//   2. LIVE (Firebase AI Logic configured): the same structure, but the
//      story text is generated by the hybrid models through hybrid-router.js.
//      The model is constrained by a strict system prompt: it may ONLY use
//      the figures, morals and sources in the content bank, must never
//      invent a Quran verse number or a hadith, and must say "I don't know"
//      rather than guess. Live output is marked "AI-generated — please
//      verify before reading to children" in the UI.
//
// Output shape (both paths):
//   { title, figureId, theme, pages: [ {heading, text} x5 ], moral,
//     sources, dialogue: [ {speaker: "oyen"|"momo", text} x2 ],
//     route, ms }
// ============================================================================

import { FIGURES, DIALOGUES, getFigure, matchFigure } from "./content-bank.js?v=4";
import { generate, ROUTES } from "./hybrid-router.js?v=4";

const PAGE_HEADINGS = {
  id: ["Awal Cerita", "Masalah Datang", "Saat Tersulit", "Pertolongan Allah", "Pelajaran"],
  en: ["The Beginning", "Trouble Comes", "The Hardest Moment", "Allah's Help", "The Lesson"],
};

const SYSTEM_PROMPT = `You write short bedtime stories for children (ages 4-9) about Islamic prophets.
STRICT RULES — breaking them is worse than refusing:
1. Use ONLY these prophets: Noah (Nuh), Job (Ayub), Jonah (Yunus), Joseph (Yusuf), Moses (Musa), Abraham (Ibrahim).
2. Use ONLY these morals: patience, obedience to Allah, never deciding while angry, praying in hardship, not envying others, forgiving others, speaking the truth bravely, helping others, never fearing because Allah is with us.
3. NEVER invent a Quran verse number, a hadith, a name, a date, or a number (such as years or amounts) that is not in the story you were given. If you are unsure, leave it out.
4. Keep every sentence short and simple. No scary details. No violence described in detail.
5. Answer in the SAME language as the user's request (Indonesian or English).
6. Reply with JSON only, exactly in this shape:
{"title": "...", "pages": [{"heading": "...", "text": "..."}, x5], "moral": "..."}`;

function splitSentences(text) {
  return (text || "").split(/(?<=[.!?])\s+/).map((s) => s.trim()).filter(Boolean);
}

// --- Template path ----------------------------------------------------------
export function buildTemplateStory({ figureId, theme, lang }) {
  const figure = getFigure(figureId);
  const L = lang === "en" ? "en" : "id";
  const story = figure.story[L];
  // Page 3 = first sentence of the climax paragraph; page 4 = the rest,
  // so no page repeats another page's text.
  const climax = splitSentences(story[2]);
  const hardest = climax.slice(0, 1).join(" ");
  const help = climax.slice(1).join(" ") || story[2];
  const pages = [
    { heading: PAGE_HEADINGS[L][0], text: story[0] },
    { heading: PAGE_HEADINGS[L][1], text: story[1] },
    { heading: PAGE_HEADINGS[L][2], text: hardest },
    { heading: PAGE_HEADINGS[L][3], text: help },
    { heading: PAGE_HEADINGS[L][4], text: story[3] + " " + figure.moral[L] },
  ];
  const dialogue = DIALOGUES[figure.id][L].map((text, i) => ({
    speaker: i % 2 === 0 ? "oyen" : "momo",
    text,
  }));
  return {
    title: L === "en"
      ? `${figure.name.en} — ${figure.theme.en}`
      : `${figure.name.id} — ${figure.theme.id}`,
    figureId: figure.id,
    theme,
    pages,
    moral: figure.moral[L],
    sources: figure.sources,
    dialogue,
    route: ROUTES.TEMPLATE,
    ms: 0,
  };
}

// --- Live path --------------------------------------------------------------
export async function buildLiveStory({ figureId, theme, lang, age }) {
  const figure = getFigure(figureId);
  const L = lang === "en" ? "en" : "id";
  const userPrompt =
    `${SYSTEM_PROMPT}\n\n` +
    `Write a 5-page bedtime story about ${figure.name.en} for a ${age}-year-old child. ` +
    `Theme from the parent: "${theme}". Moral to teach: ${figure.moral.en}. ` +
    `Keep the story close to the well-known retelling; do not add new characters, ` +
    `dates, numbers, verses or hadith. Language: ${L === "en" ? "English" : "Bahasa Indonesia"}.`;

  const res = await generate("story", userPrompt);
  if (!res.text) return { story: null, error: res.error, route: res.route, ms: res.ms };

  let parsed = null;
  try {
    const jsonText = res.text.replace(/^```json\s*/i, "").replace(/```\s*$/i, "").trim();
    parsed = JSON.parse(jsonText);
  } catch {
    parsed = null;
  }
  if (!parsed || !Array.isArray(parsed.pages) || parsed.pages.length < 3) {
    return { story: null, error: "Live model returned unparsable output — falling back to verified template.", route: res.route, ms: res.ms };
  }

  const dialogue = DIALOGUES[figure.id][L].map((text, i) => ({
    speaker: i % 2 === 0 ? "oyen" : "momo",
    text,
  }));
  return {
    story: {
      title: parsed.title || figure.name[L],
      figureId: figure.id,
      theme,
      pages: parsed.pages.slice(0, 5).map((p, i) => ({
        heading: p.heading || PAGE_HEADINGS[L][i] || `Page ${i + 1}`,
        text: p.text || "",
      })),
      moral: parsed.moral || figure.moral[L],
      sources: figure.sources,
      dialogue,
      route: res.route,
      ms: res.ms,
    },
    error: null,
    route: res.route,
    ms: res.ms,
  };
}

// --- Quick on-device tasks --------------------------------------------------
export async function quickMoral(figureId, lang) {
  const figure = getFigure(figureId);
  const res = await generate(
    "quick",
    `In ONE short sentence (max 15 words), what is the moral of the story of ${figure.name.en}? ` +
      `Answer in ${lang === "en" ? "English" : "Bahasa Indonesia"}.`
  );
  if (res.text) return { text: res.text.replace(/^["']|["']$/g, ""), route: res.route, ms: res.ms };
  return { text: figure.moral[lang === "en" ? "en" : "id"], route: ROUTES.TEMPLATE, ms: 0 };
}

export function suggestFigure(theme) {
  const { figure, score } = matchFigure(theme);
  return { figure: figure || FIGURES[0], score };
}

export { FIGURES };
